<?php
declare(strict_types=1);
const CAL_AUTH_FILE = __DIR__.'/storage/auth/users.json';
function cal_auth_start(): void { if(session_status()!==PHP_SESSION_ACTIVE)session_start(); }
function cal_auth_users(): array { if(!is_file(CAL_AUTH_FILE))return []; $v=json_decode((string)file_get_contents(CAL_AUTH_FILE),true);return is_array($v)?array_values(array_filter($v,'is_array')):[]; }
function cal_auth_save(array $users): void { $dir=dirname(CAL_AUTH_FILE);if(!is_dir($dir)&&!mkdir($dir,0770,true)&&!is_dir($dir))throw new RuntimeException('Auth-Speicher konnte nicht angelegt werden.');$tmp=CAL_AUTH_FILE.'.tmp';$json=json_encode(array_values($users),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if(file_put_contents($tmp,$json,LOCK_EX)===false)throw new RuntimeException('Benutzer konnten nicht gespeichert werden.');rename($tmp,CAL_AUTH_FILE); }
function cal_auth_ready(): bool { return count(cal_auth_users())>0; }
function cal_auth_role_rank(string $role): int { return ['viewer'=>10,'editor'=>20,'admin'=>30][$role]??0; }
function cal_auth_user(): ?array { cal_auth_start();$id=(int)($_SESSION['calendar_user_id']??0);if($id<1)return null;foreach(cal_auth_users() as $u)if((int)($u['id']??0)===$id&&!empty($u['active']))return $u;return null; }
function cal_auth_login(string $identity,string $password): bool { $identity=strtolower(trim($identity));foreach(cal_auth_users() as $u){if(empty($u['active']))continue;$name=strtolower((string)($u['username']??''));$mail=strtolower((string)($u['email']??''));if(($identity===$name||($mail!==''&&$identity===$mail))&&password_verify($password,(string)($u['password_hash']??''))){cal_auth_start();session_regenerate_id(true);$_SESSION['calendar_user_id']=(int)$u['id'];return true;}}return false; }
function cal_auth_logout(): void { cal_auth_start();unset($_SESSION['calendar_user_id']);session_regenerate_id(true); }
function cal_auth_require(string $role='viewer'): array { if(!cal_auth_ready()){header('Location: setup.php');exit;} $u=cal_auth_user();if(!$u){$next=rawurlencode((string)($_SERVER['REQUEST_URI']??'index.php'));header('Location: login.php?next='.$next);exit;}if(cal_auth_role_rank((string)($u['role']??'viewer'))<cal_auth_role_rank($role)){http_response_code(403);exit('Keine Berechtigung.');}return $u; }
function cal_auth_can(string $role): bool { $u=cal_auth_user();return $u&&cal_auth_role_rank((string)$u['role'])>=cal_auth_role_rank($role); }
function cal_auth_add_first_admin(string $username,string $email,string $password): void { if(cal_auth_ready())throw new RuntimeException('Ein Administrator ist bereits eingerichtet.');$username=trim($username);if(!preg_match('/^[A-Za-z0-9._-]{3,100}$/',$username))throw new RuntimeException('Benutzername ist ungültig.');if(strlen($password)<10||!preg_match('/[A-Z]/',$password)||!preg_match('/[a-z]/',$password)||!preg_match('/\d/',$password))throw new RuntimeException('Kennwort: mindestens 10 Zeichen, Groß-/Kleinbuchstaben und Ziffer.');cal_auth_save([['id'=>1,'username'=>$username,'email'=>trim($email),'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>'admin','active'=>true,'created_at'=>date('c')]]); }
function cal_auth_upsert(array $in): void { $actor=cal_auth_require('admin');$users=cal_auth_users();$id=max(0,(int)($in['id']??0));$username=trim((string)($in['username']??''));$email=trim((string)($in['email']??''));$role=(string)($in['role']??'viewer');if(!in_array($role,['admin','editor','viewer'],true))throw new RuntimeException('Ungültige Rolle.');if(!preg_match('/^[A-Za-z0-9._-]{3,100}$/',$username))throw new RuntimeException('Benutzername ist ungültig.');foreach($users as $u)if((int)$u['id']!==$id&&(strcasecmp((string)$u['username'],$username)===0||($email!==''&&strcasecmp((string)($u['email']??''),$email)===0)))throw new RuntimeException('Benutzername/E-Mail ist bereits vergeben.');$idx=null;foreach($users as $i=>$u)if((int)$u['id']===$id)$idx=$i;$password=(string)($in['password']??'');if($id<1){if(strlen($password)<10)throw new RuntimeException('Für neue Benutzer ist ein Kennwort mit mindestens 10 Zeichen erforderlich.');$id=max(array_map(fn($u)=>(int)($u['id']??0),$users)?:[0])+1;$users[]=['id'=>$id,'username'=>$username,'email'=>$email,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role,'active'=>!empty($in['active']),'created_at'=>date('c')];}else{if($idx===null)throw new RuntimeException('Benutzer nicht gefunden.');$users[$idx]['username']=$username;$users[$idx]['email']=$email;$users[$idx]['role']=$role;$users[$idx]['active']=!empty($in['active']);if($password!==''){$users[$idx]['password_hash']=password_hash($password,PASSWORD_DEFAULT);}if((int)$actor['id']===$id&&!$users[$idx]['active'])throw new RuntimeException('Das eigene Administratorkonto kann nicht deaktiviert werden.');}cal_auth_save($users); }
